cssCode:
html, body, #container { margin: 0; width: 100%; height: 100%; overflow: hidden; background: transparent; }
.gravity-text {
  font-size: 60px; font-weight: 900; font-family: sans-serif;
  color: #ff007f; text-shadow: 0 0 20px rgba(255,0,127,0.6);
  position: absolute; cursor: pointer; user-select: none;
  touch-action: none; display: flex; gap: 5px;
}
.g-letter {
  display: inline-block; position: relative;
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;position:relative;background:transparent;overflow:hidden;display:flex;align-items:center;justify-content:center;';

const textWrap = document.createElement('div');
textWrap.className = 'gravity-text';
const word = "BOUNCE";
const letters = [];

word.split('').forEach((l) => {
  const span = document.createElement('span');
  span.className = 'g-letter';
  span.innerText = l;
  span.y = 0; span.vy = 0;
  letters.push(span);
  textWrap.appendChild(span);
});
c.appendChild(textWrap);

let isFalling = false;

textWrap.addEventListener('pointerdown', () => {
  if(isFalling) return;
  isFalling = true;
  letters.forEach((span) => {
    span.vy = -(Math.random() * 15 + 10); // Upar no dhakko
  });
});

function animateGravity() {
  if (isFalling) {
    let allSettled = true;
    letters.forEach((span) => {
      span.vy += 0.8; // Gravity
      span.y += span.vy;
      if (span.y > 0) {
        span.y = 0;
        span.vy *= -0.6; // Bounce
        if (Math.abs(span.vy) > 1) allSettled = false;
      } else {
        allSettled = false;
      }
      span.style.transform = `translateY(${span.y}px)`;
    });
    if (allSettled) isFalling = false;
  }
  requestAnimationFrame(animateGravity);
}
animateGravity();
